/*!40000 ALTER TABLE `applicant_requirements` ENABLE KEYS */;
UNLOCK TABLES;
DROP TABLE IF EXISTS `applicants`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `applicants` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `applicant_no` varchar(16) NOT NULL,
  `first_name` varchar(60) NOT NULL,
  `middle_name` varchar(60) DEFAULT NULL,
  `last_name` varchar(60) NOT NULL,
  `sex` char(1) NOT NULL,
  `email` varchar(120) NOT NULL,
  `program_id` smallint(5) unsigned NOT NULL,
  `type` enum('Freshman','Transferee') NOT NULL,
  `shs_strand` varchar(10) DEFAULT NULL,
  `prior_gwa` decimal(5,2) DEFAULT NULL,
  `exam_date` date DEFAULT NULL,
  `exam_score` tinyint(3) unsigned DEFAULT NULL,
  `status` enum('For review','Not qualified','Qualified','Pending documents','Enrolled') NOT NULL,
  `submitted_at` datetime NOT NULL,
  `updated_at` datetime NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `applicant_no` (`applicant_no`),
  KEY `idx_applicants_status` (`status`),
  KEY `idx_applicants_updated` (`updated_at`),
  KEY `program_id` (`program_id`),
  CONSTRAINT `applicants_ibfk_1` FOREIGN KEY (`program_id`) REFERENCES `programs` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=3241 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

LOCK TABLES `applicants` WRITE;
