INSERT INTO `colleges` VALUES (1,'CCS','College of Computing Studies','Computing','CCS Building'),(2,'COE','College of Engineering','Engineering','Engineering Building'),(3,'CBA','College of Business and Accountancy','Business','Business Building'),(4,'CAS','College of Arts and Sciences','Arts & Sciences','Arts and Sciences Building'),(5,'COED','College of Education','Education','Education Building'),(6,'CHS','College of Health Sciences','Health Sciences','Health Sciences Building');
