  `id` smallint(5) unsigned NOT NULL AUTO_INCREMENT,
  `college_id` tinyint(3) unsigned NOT NULL,
  `code` varchar(20) NOT NULL,
  `title` varchar(120) NOT NULL,
  `units` tinyint(3) unsigned NOT NULL,
  `kind` enum('Lecture','Lab','PE','NSTP','Practicum') NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `code` (`code`),
  KEY `college_id` (`college_id`),
  CONSTRAINT `courses_ibfk_1` FOREIGN KEY (`college_id`) REFERENCES `colleges` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=219 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
