DROP TABLE IF EXISTS `faculty_rating_history`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `faculty_rating_history` (
  `faculty_id` smallint(5) unsigned NOT NULL,
  `term_id` tinyint(3) unsigned NOT NULL,
  `rating` decimal(3,2) NOT NULL,
  `responses` smallint(5) unsigned NOT NULL,
  PRIMARY KEY (`faculty_id`,`term_id`),
  KEY `term_id` (`term_id`),
  CONSTRAINT `faculty_rating_history_ibfk_1` FOREIGN KEY (`faculty_id`) REFERENCES `faculty` (`id`),
  CONSTRAINT `faculty_rating_history_ibfk_2` FOREIGN KEY (`term_id`) REFERENCES `terms` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

