DROP TABLE IF EXISTS `sections`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `sections` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `term_id` tinyint(3) unsigned NOT NULL,
  `course_id` smallint(5) unsigned NOT NULL,
  `program_id` smallint(5) unsigned NOT NULL,
  `year_level` tinyint(3) unsigned NOT NULL,
  `block` char(1) NOT NULL,
  `faculty_id` smallint(5) unsigned DEFAULT NULL,
  `mode` enum('Onsite','Online','Off-campus') NOT NULL DEFAULT 'Onsite',
  `platform` varchar(30) DEFAULT NULL,
  `grades_updated_at` datetime DEFAULT NULL,
  `grades_submitted_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_section` (`term_id`,`course_id`,`program_id`,`year_level`,`block`),
  KEY `idx_sections_faculty` (`faculty_id`),
  KEY `course_id` (`course_id`),
  KEY `program_id` (`program_id`),
  CONSTRAINT `sections_ibfk_1` FOREIGN KEY (`term_id`) REFERENCES `terms` (`id`),
  CONSTRAINT `sections_ibfk_2` FOREIGN KEY (`course_id`) REFERENCES `courses` (`id`),
  CONSTRAINT `sections_ibfk_3` FOREIGN KEY (`program_id`) REFERENCES `programs` (`id`),
  CONSTRAINT `sections_ibfk_4` FOREIGN KEY (`faculty_id`) REFERENCES `faculty` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=1043 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

LOCK TABLES `sections` WRITE;
