DROP TABLE IF EXISTS `students`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `students` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `student_no` varchar(12) NOT NULL,
  `first_name` varchar(60) NOT NULL,
  `middle_name` varchar(60) DEFAULT NULL,
  `last_name` varchar(60) NOT NULL,
  `sex` char(1) NOT NULL,
  `birthdate` date NOT NULL,
  `email` varchar(120) NOT NULL,
  `program_id` smallint(5) unsigned NOT NULL,
  `year_level` tinyint(3) unsigned NOT NULL,
  `block` char(1) NOT NULL,
  `status` enum('Regular','Irregular','On leave') NOT NULL,
  `back_subjects` tinyint(3) unsigned NOT NULL DEFAULT 0,
  `adviser_id` smallint(5) unsigned DEFAULT NULL,
  `enrolled_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `student_no` (`student_no`),
  UNIQUE KEY `email` (`email`),
  KEY `idx_students_program` (`program_id`,`year_level`,`block`),
  KEY `idx_students_name` (`last_name`,`first_name`),
  KEY `adviser_id` (`adviser_id`),
  CONSTRAINT `students_ibfk_1` FOREIGN KEY (`program_id`) REFERENCES `programs` (`id`),
  CONSTRAINT `students_ibfk_2` FOREIGN KEY (`adviser_id`) REFERENCES `faculty` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=5843 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

LOCK TABLES `students` WRITE;
